class Solution:
    def countArrangement(self, n: int) -> int:
        dp = [0] * (1 << n)
        dp[0] = 1
        for mask in range(1 << n):
            position = mask.bit_count() + 1
            for number in range(1, n + 1):
                bit = 1 << (number - 1)
                if not mask & bit and (number % position == 0 or position % number == 0):
                    dp[mask | bit] += dp[mask]
        return dp[-1]
